const { createHash } = require('crypto');
const envelope = $input.first().json;
if (envelope.execution_mode !== 'OFFLINE_EVAL' || envelope.external_effects_allowed !== false) throw new Error('WF-03 aceita somente OFFLINE_EVAL sem efeitos externos');
if (!envelope.registration?.event_id || !envelope.routing?.routing_id) throw new Error('Evento persistido ou roteamento ausente');
if (!['DETERMINISTIC', 'MODEL_ASSISTED'].includes(envelope.routing.routing_method)) throw new Error('Método de roteamento inválido');
if (!['READY', 'MANUAL_REVIEW_REQUIRED'].includes(envelope.routing.decision_status)) throw new Error('Estado decisório do roteamento inválido');
const canonical = JSON.stringify({ event_id: envelope.registration.event_id, routing: envelope.routing });
return [{ json: { ...envelope, routing_audit_hash: `sha256:${createHash('sha256').update(canonical, 'utf8').digest('hex')}` } }];

const row = $input.first().json;
const envelope = typeof row.envelope === 'string' ? JSON.parse(row.envelope) : row.envelope;
if (!envelope || !row.registration_status) throw new Error('Banco não retornou o registro do roteamento');
delete envelope.routing_audit_hash;
return [{ json: { ...envelope, routing_registration: { routing_id: row.routing_id, event_id: row.event_id, registration_status: row.registration_status, decision_status: row.decision_status, is_new: row.is_new === true, audit_id: Number(row.audit_id), registered_at: row.created_at } } }];
